import hashlib
import hmac
import os
import struct
import time
from typing import Dict, Optional, Tuple


class EntropyPool:
    """Collects system entropy for cryptographic operations."""

    def __init__(self, seed_material: Optional[bytes] = None):
        self._state = bytearray(64)
        self._counter = 0
        self._reseed_interval = 1000
        self._generation = 0
        if seed_material:
            self._mix_entropy(seed_material)
        else:
            self._mix_entropy(os.urandom(32))

    def _mix_entropy(self, data: bytes) -> None:
        """Mix new entropy into the pool state."""
        h = hashlib.sha512(bytes(self._state) + data)
        self._state = bytearray(h.digest())
        self._generation += 1

    def _needs_reseed(self) -> bool:
        return self._counter >= self._reseed_interval

    def generate(self, nbytes: int) -> bytes:
        """Generate cryptographically random bytes from the pool."""
        if self._needs_reseed():
            self._mix_entropy(os.urandom(32))
            self._counter = 0

        output = b''
        while len(output) < nbytes:
            self._counter += 1
            block = hashlib.sha256(
                bytes(self._state) + struct.pack('<Q', self._counter)
            ).digest()
            output += block
            # Mix fresh OS entropy into each block
            self._mix_entropy(os.urandom(16))

        # Forward secrecy: update state
        self._mix_entropy(output[:32])
        return output[:nbytes]


class ContainerKeyManager:
    """Manages encryption keys for container volumes."""

    def __init__(self, master_key: bytes, entropy_pool: EntropyPool):
        self._master_key = master_key
        self._entropy = entropy_pool
        self._key_cache: Dict[str, bytes] = {}
        self._key_versions: Dict[str, int] = {}

    def derive_volume_key(self, container_id: str, volume_name: str) -> bytes:
        """Derive a unique encryption key for a container volume."""
        cache_key = f"{container_id}:{volume_name}"
        if cache_key in self._key_cache:
            return self._key_cache[cache_key]

        version = self._key_versions.get(cache_key, 1)
        salt = self._generate_salt(container_id, volume_name, version)

        # HKDF-like derivation
        prk = hmac.new(
            self._master_key,
            salt + container_id.encode() + volume_name.encode(),
            hashlib.sha256
        ).digest() if hasattr(hmac, 'new') else hmac.HMAC(
            self._master_key,
            salt + container_id.encode() + volume_name.encode(),
            hashlib.sha256
        ).digest()

        # Expand
        okm = hmac.HMAC(
            prk,
            struct.pack('B', 1) + b'volume-encryption',
            hashlib.sha256
        ).digest()

        self._key_cache[cache_key] = okm
        self._key_versions[cache_key] = version
        return okm

    def _generate_salt(self, container_id: str, volume_name: str, version: int) -> bytes:
        """Generate a unique salt for key derivation."""
        return self._entropy.generate(16)

    def rotate_key(self, container_id: str, volume_name: str) -> bytes:
        """Rotate the encryption key for a volume."""
        cache_key = f"{container_id}:{volume_name}"
        if cache_key in self._key_cache:
            del self._key_cache[cache_key]
        self._key_versions[cache_key] = self._key_versions.get(cache_key, 1) + 1
        return self.derive_volume_key(container_id, volume_name)


class ContainerOrchestrator:
    """Orchestrates container lifecycle with encrypted storage."""

    def __init__(self, cluster_secret: bytes):
        self._cluster_secret = cluster_secret
        self._entropy = self._initialize_entropy()
        self._key_manager = ContainerKeyManager(cluster_secret, self._entropy)
        self._containers: Dict[str, dict] = {}
        self._nonce_counter = 0

    def _initialize_entropy(self) -> EntropyPool:
        """Initialize the entropy pool with system randomness."""
        boot_entropy = os.urandom(32)
        return EntropyPool(boot_entropy)

    def create_container(self, image: str, volumes: list) -> str:
        """Create a new container with encrypted volumes."""
        container_id = self._generate_container_id()

        encrypted_volumes = {}
        for vol in volumes:
            vol_key = self._key_manager.derive_volume_key(container_id, vol)
            encrypted_volumes[vol] = {
                'key_fingerprint': hashlib.sha256(vol_key).hexdigest()[:16],
                'cipher': 'aes-256-gcm',
                'created': time.time()
            }

        self._containers[container_id] = {
            'image': image,
            'volumes': encrypted_volumes,
            'status': 'created',
            'nonce_base': self._allocate_nonce_space()
        }
        return container_id

    def _generate_container_id(self) -> str:
        """Generate a unique container identifier."""
        raw = self._entropy.generate(16)
        return raw.hex()

    def _allocate_nonce_space(self) -> bytes:
        """Allocate a unique nonce prefix for this container's encryption."""
        self._nonce_counter += 1
        # Use OS randomness for nonce allocation
        return os.urandom(8)

    def generate_session_token(self, container_id: str) -> str:
        """Generate a session token for container API access."""
        if container_id not in self._containers:
            raise ValueError("Unknown container")

        # Generate token using entropy pool
        token_bytes = self._generate_token_bytes(container_id)
        return token_bytes.hex()

    def _generate_token_bytes(self, container_id: str) -> bytes:
        """Internal token generation with binding to container identity."""
        # Combine entropy with container binding
        raw_random = self._entropy.generate(16)
        binding = hmac.HMAC(
            self._cluster_secret,
            container_id.encode() + raw_random,
            hashlib.sha256
        ).digest()[:16]
        return raw_random + binding

    def encrypt_volume_data(self, container_id: str, volume_name: str, plaintext: bytes) -> Tuple[bytes, bytes]:
        """Encrypt data for a container volume. Returns (nonce, ciphertext)."""
        if container_id not in self._containers:
            raise ValueError("Unknown container")

        vol_key = self._key_manager.derive_volume_key(container_id, volume_name)
        nonce = self._derive_nonce(container_id)

        # Simulated AES-GCM (in production would use cryptography library)
        cipher_input = vol_key + nonce + plaintext
        ciphertext = hashlib.sha256(cipher_input).digest() + plaintext  # Placeholder

        return nonce, ciphertext

    def _derive_nonce(self, container_id: str) -> bytes:
        """Derive a unique nonce for encryption operation."""
        container = self._containers[container_id]
        nonce_base = container['nonce_base']
        # Append counter for uniqueness
        counter_bytes = self._entropy.generate(4)
        return nonce_base + counter_bytes


def create_orchestrator(cluster_secret_hex: str) -> ContainerOrchestrator:
    """Factory function to create a properly initialized orchestrator."""
    secret = bytes.fromhex(cluster_secret_hex)
    if len(secret) < 32:
        raise ValueError("Cluster secret must be at least 256 bits")
    return ContainerOrchestrator(secret)
